{
  "timeline": [
    {
      "date": "1300",
      "headline": "Proto-Renaissance Begins",
      "text": "The Proto-Renaissance period begins in Italy, characterized by a renewed interest in classical antiquity and the early developments in art and culture that would lead to the Renaissance."
    },
    {
      "date": "1401",
      "headline": "Competition for Florence Baptistery Doors",
      "text": "A competition is held to design the bronze doors of the Florence Baptistery. Lorenzo Ghiberti wins, marking a significant moment in Renaissance art."
    },
    {
      "date": "1420",
      "headline": "Brunelleschi's Dome",
      "text": "Filippo Brunelleschi begins work on the dome of the Florence Cathedral, a masterpiece of engineering and a symbol of Renaissance architecture."
    },
    {
      "date": "1434",
      "headline": "Medici Family Rises to Power",
      "text": "Cosimo de' Medici becomes the de facto ruler of Florence, establishing the Medici family's influence over the city and its patronage of the arts."
    },
    {
      "date": "1450",
      "headline": "Printing Press Invented",
      "text": "Johannes Gutenberg invents the movable-type printing press, revolutionizing the spread of knowledge and ideas across Europe."
    },
    {
      "date": "1453",
      "headline": "Fall of Constantinople",
      "text": "The fall of Constantinople to the Ottoman Empire marks the end of the Byzantine Empire and leads to the migration of Greek scholars to Italy, fueling the Renaissance."
    },
    {
      "date": "1469",
      "headline": "Lorenzo de' Medici's Rule",
      "text": "Lorenzo de' Medici, known as Lorenzo the Magnificent, begins his rule in Florence, becoming a major patron of Renaissance art and culture."
    },
    {
      "date": "1485",
      "headline": "Birth of Humanism",
      "text": "Humanism, a Renaissance cultural movement that turned away from medieval scholasticism and revived interest in ancient Greek and Roman thought, gains prominence."
    },
    {
      "date": "1492",
      "headline": "Columbus Discovers America",
      "text": "Christopher Columbus's voyage leads to the discovery of the Americas, marking the beginning of European exploration and expansion."
    },
    {
      "date": "1494",
      "headline": "French Invasion of Italy",
      "text": "The French invasion of Italy begins, leading to the Italian Wars and spreading Renaissance ideas throughout Europe."
    },
    {
      "date": "1503",
      "headline": "Mona Lisa Painted",
      "text": "Leonardo da Vinci paints the Mona Lisa, one of the most famous works of art from the Renaissance period."
    },
    {
      "date": "1512",
      "headline": "Sistine Chapel Ceiling Completed",
      "text": "Michelangelo completes the ceiling of the Sistine Chapel in Vatican City, a masterpiece of Renaissance art."
    },
    {
      "date": "1517",
      "headline": "Martin Luther's 95 Theses",
      "text": "Martin Luther nails his 95 Theses to the door of the Wittenberg Castle church, sparking the Protestant Reformation and challenging the Catholic Church's authority."
    },
    {
      "date": "1527",
      "headline": "Sack of Rome",
      "text": "The Sack of Rome by the troops of Charles V marks the end of the High Renaissance in Italy."
    },
    {
      "date": "1543",
      "headline": "Copernicus' Heliocentric Theory",
      "text": "Nicolaus Copernicus publishes 'On the Revolutions of the Celestial Spheres,' proposing a heliocentric model of the universe."
    },
    {
      "date": "1564",
      "headline": "Death of Michelangelo",
      "text": "Michelangelo, one of the most renowned artists of the Renaissance, dies in Rome."
    },
    {
      "date": "1600",
      "headline": "End of the Renaissance",
      "text": "The Renaissance period is generally considered to have ended around this time, transitioning into the Baroque period."
    }
  ]
}

