      "date": "-0190",
      "headline": "Archimedes' Approximation",
      "text": "Archimedes of Syracuse approximated π by inscribing and circumscribing polygons around a circle and calculating their perimeters. He found that π is between 3 1/7 (approximately 3.1429) and 3 10/71 (approximately 3.1408)."
    },
    {
      "date": "0140",
      "headline": "Ptolemy's Calculation",
      "text": "Claudius Ptolemy, in his work Almagest, calculated π as 3.1416 using a 360-sided polygon."
    },
    {
      "date": "0499",
      "headline": "Aryabhata's Approximation",
      "text": "Indian mathematician Aryabhata approximated π as 3.1416 in his astronomical treatise Aryabhatiya."
    },
    {
      "date": "1424",
      "headline": "Madhava's Series",
      "text": "Madhava of Sangamagrama developed the Madhava-Leibniz series, an infinite series that converges to π, marking a significant advancement in the calculation of π."
    },
    {
      "date": "1596",
      "headline": "Ludolph van Ceulen's Calculation",
      "text": "Ludolph van Ceulen calculated π to 20 decimal places using polygons with 2^62 sides. His work was so significant that π was sometimes referred to as 'Ludolph's number'."
    },
    {
      "date": "1706",
      "headline": "Introduction of the Symbol π",
      "text": "Welsh mathematician William Jones introduced the symbol π to represent the ratio of the circumference of a circle to its diameter."
    },
    {
      "date": "1761",
      "headline": "Proving π is Irrational",
      "text": "Johann Lambert proved that π is an irrational number, meaning it cannot be expressed as a fraction of two integers."
    },
    {
      "date": "1882",
      "headline": "Proving π is Transcendental",
      "text": "Ferdinand von Lindemann proved that π is a transcendental number, confirming that it is impossible to square the circle using only a compass and straightedge."
    },
    {
      "date": "1949",
      "headline": "First Computer Calculation",
      "text": "The ENIAC computer calculated π to 2,037 decimal places, marking the first time a computer was used to calculate π."
    },
    {
      "date": "1989",
      "headline": "Chudnovsky Brothers' Record",
      "text": "David and Gregory Chudnovsky used a supercomputer to calculate π to over 1 billion decimal places."
    },
    {
      "date": "2021",
      "headline": "New Record for Decimal Places",
      "text": "Researchers at the University of Applied Sciences of the Grisons in Switzerland calculated π to 62.8 trillion decimal places, setting a new world record."
    }
  ]
}

