{
  "timeline": [
    {
      "date": "1986-01-28",
      "headline": "Space Shuttle Challenger Disaster",
      "text": "On January 28, 1986, the Space Shuttle Challenger broke apart 73 seconds into its flight, killing all seven crew members aboard. The spacecraft disintegrated 46,000 feet (14 km) above the Atlantic Ocean, off the coast of Cape Canaveral, Florida, at 11:39 a.m. EST. It was the first fatal accident involving an American spacecraft while in flight."
    },
    {
      "date": "1986-01-28",
      "headline": "Crew Members Lost",
      "text": "The disaster resulted in the deaths of all seven crew members: Francis R. Scobee (Commander), Michael J. Smith (Pilot), Ronald McNair (Mission Specialist), Ellison Onizuka (Mission Specialist), Judith Resnik (Mission Specialist), Gregory Jarvis (Payload Specialist), and Christa McAuliffe (Payload Specialist and Teacher in Space)."
    },
    {
      "date": "1986-01-28",
      "headline": "Cause of Disaster",
      "text": "The disaster was caused by the failure of an O-ring seal in its right solid rocket booster (SRB). The O-ring failure caused a breach in the SRB joint it sealed, allowing pressurized burning gas from within the solid rocket motor to reach the outside and impinge upon the adjacent SRB aft field joint attachment hardware and external fuel tank."
    },
    {
      "date": "1986-02",
      "headline": "Presidential Commission on the Space Shuttle Challenger Accident",
      "text": "In February 1986, President Ronald Reagan appointed a special commission to investigate the Challenger disaster. The commission was chaired by former Secretary of State William P. Rogers and included notable members such as astronaut Neil Armstrong and physicist Richard Feynman."
    },
    {
      "date": "1986-06",
      "headline": "Rogers Commission Report",
      "text": "The Rogers Commission Report was published in June 1986, detailing the technical and organizational failures that led to the Challenger disaster. It identified the failure of the O-rings and criticized NASA's management and decision-making processes."
    },
    {
      "date": "1988-09-29",
      "headline": "Return to Flight",
      "text": "NASA returned to flight with the launch of Space Shuttle Discovery on September 29, 1988, with the STS-26 mission. This marked the resumption of the Space Shuttle program after a 32-month hiatus following the Challenger disaster."
    }
  ]
}

