{
  "timeline": [
    {
      "date": "-1000",
      "headline": "First Inhabitants",
      "text": "The first known inhabitants of Aruba were the Arawak Caquetío Amerindians from the South American mainland, who migrated to the island around 1000 BCE."
    },
    {
      "date": "1499",
      "headline": "Discovery by Europeans",
      "text": "Aruba was discovered by Spanish explorer Alonso de Ojeda in 1499, marking the beginning of European interest in the island."
    },
    {
      "date": "1636",
      "headline": "Dutch Control",
      "text": "The Dutch took control of Aruba in 1636, as part of their colonial expansion in the Caribbean."
    },
    {
      "date": "1805",
      "headline": "British Occupation",
      "text": "During the Napoleonic Wars, Aruba was occupied by the British from 1805 to 1816."
    },
    {
      "date": "1816",
      "headline": "Return to Dutch Rule",
      "text": "Aruba was returned to Dutch control in 1816 following the end of the Napoleonic Wars."
    },
    {
      "date": "1924",
      "headline": "Oil Refinery Established",
      "text": "The Lago Oil and Transport Company established an oil refinery in Aruba in 1924, significantly boosting the island's economy."
    },
    {
      "date": "1947",
      "headline": "First Aruban Flag",
      "text": "Aruba adopted its first flag in 1947, symbolizing a growing sense of national identity."
    },
    {
      "date": "1954",
      "headline": "Netherlands Antilles Formation",
      "text": "Aruba became part of the Netherlands Antilles, a political grouping of Dutch Caribbean territories, in 1954."
    },
    {
      "date": "1976",
      "headline": "Aruban Flag and Anthem",
      "text": "Aruba adopted its own flag and national anthem, 'Aruba Dushi Tera,' in 1976, furthering its cultural identity."
    },
    {
      "date": "1986-01-01",
      "headline": "Status Aparte",
      "text": "Aruba seceded from the Netherlands Antilles and became a separate constituent country within the Kingdom of the Netherlands, a status known as 'Status Aparte.'"
    },
    {
      "date": "1996",
      "headline": "20th Anniversary of Status Aparte",
      "text": "Aruba celebrated the 20th anniversary of its Status Aparte, marking two decades of autonomy within the Kingdom of the Netherlands."
    },
    {
      "date": "2010-10-10",
      "headline": "Dissolution of Netherlands Antilles",
      "text": "The Netherlands Antilles was dissolved, and Aruba continued as a separate entity within the Kingdom of the Netherlands, alongside Curaçao and Sint Maarten."
    }
  ]
}

