{
  "timeline": [
    {
      "date": "1935",
      "headline": "First Lobotomy Performed",
      "text": "Portuguese neurologist António Egas Moniz performed the first lobotomy, which he called a 'leucotomy', in Lisbon. The procedure involved drilling holes in the patient's skull and injecting alcohol into the frontal lobes to destroy the white matter."
    },
    {
      "date": "1936",
      "headline": "Development of the Prefrontal Lobotomy",
      "text": "American neurologist Walter Freeman and neurosurgeon James W. Watts developed the prefrontal lobotomy, a surgical procedure that involved cutting the connections to and from the prefrontal cortex."
    },
    {
      "date": "1949",
      "headline": "Nobel Prize Awarded",
      "text": "António Egas Moniz was awarded the Nobel Prize in Physiology or Medicine for his development of the lobotomy, despite controversy over the ethics and effectiveness of the procedure."
    },
    {
      "date": "1950s",
      "headline": "Peak Popularity of Lobotomy",
      "text": "Lobotomies became a common treatment for various mental illnesses in the United States and Europe, with thousands of procedures performed annually."
    },
    {
      "date": "1954",
      "headline": "Introduction of Thorazine",
      "text": "The introduction of the antipsychotic drug Thorazine (chlorpromazine) provided a less invasive treatment option for mental illness, leading to a decline in the use of lobotomies."
    },
    {
      "date": "1967",
      "headline": "Last Lobotomy by Walter Freeman",
      "text": "Walter Freeman performed his last lobotomy, marking the end of an era for the procedure as it fell out of favor due to ethical concerns and the development of more effective psychiatric medications."
    },
    {
      "date": "1970s",
      "headline": "Decline of Lobotomy",
      "text": "The lobotomy procedure was largely abandoned in the 1970s as psychiatric drugs became more effective and ethical standards in medicine improved."
    }
  ]
}

