    {
      "date": "1907",
      "headline": "Meeting with Sigmund Freud",
      "text": "Jung met Sigmund Freud in Vienna, marking the beginning of a close collaboration and friendship that lasted several years."
    },
    {
      "date": "1912",
      "headline": "Publication of 'Psychology of the Unconscious'",
      "text": "Jung published 'Psychology of the Unconscious', which marked a divergence from Freud's theories and laid the foundation for his own analytical psychology."
    },
    {
      "date": "1913",
      "headline": "Break with Freud",
      "text": "Jung's relationship with Freud ended due to theoretical disagreements, particularly over the nature of the unconscious."
    },
    {
      "date": "1921",
      "headline": "Publication of 'Psychological Types'",
      "text": "Jung published 'Psychological Types', introducing the concepts of introversion and extraversion, and the four psychological functions."
    },
    {
      "date": "1933",
      "headline": "Appointment as Professor at ETH Zurich",
      "text": "Jung was appointed as a professor of medical psychology at the Swiss Federal Institute of Technology in Zurich."
    },
    {
      "date": "1944",
      "headline": "Publication of 'Psychology and Alchemy'",
      "text": "Jung published 'Psychology and Alchemy', exploring the relationship between alchemical symbolism and psychological processes."
    },
    {
      "date": "1948",
      "headline": "Founding of the C.G. Jung Institute",
      "text": "The C.G. Jung Institute was founded in Zurich to promote the study and practice of Jungian psychology."
    },
    {
      "date": "1952",
      "headline": "Publication of 'Synchronicity: An Acausal Connecting Principle'",
      "text": "Jung published his work on synchronicity, proposing a principle of meaningful coincidences."
    },
    {
      "date": "1961-06-06",
      "headline": "Death of Carl Jung",
