{
  "timeline": [
    {
      "date": "-0600",
      "headline": "Pre-Socratic Philosophy",
      "text": "The Pre-Socratic philosophers, such as Thales, Anaximander, and Heraclitus, begin to explore the nature of the universe, laying the groundwork for Western philosophy."
    },
    {
      "date": "-0428",
      "headline": "Birth of Plato",
      "text": "Plato, a student of Socrates and teacher of Aristotle, is born in Athens. He would go on to found the Academy and write numerous philosophical dialogues."
    },
    {
      "date": "-0384",
      "headline": "Birth of Aristotle",
      "text": "Aristotle, a student of Plato and tutor to Alexander the Great, is born in Stagira. He would make significant contributions to numerous fields, including logic, metaphysics, and ethics."
    },
    {
      "date": "-0335",
      "headline": "Founding of the Lyceum",
      "text": "Aristotle founds the Lyceum in Athens, where he conducts research and teaches a wide range of subjects, influencing Western thought for centuries."
    },
    {
      "date": "0000",
      "headline": "Development of Christian Philosophy",
      "text": "Christian philosophy begins to develop, integrating Greek philosophical concepts with Christian theology, significantly influencing medieval thought."
    },
    {
      "date": "1225",
      "headline": "Birth of Thomas Aquinas",
      "text": "Thomas Aquinas, a Dominican friar and theologian, is born. He would become a central figure in Scholastic philosophy, synthesizing Aristotelian philosophy with Christian doctrine."
    },
    {
      "date": "1781",
      "headline": "Publication of Critique of Pure Reason",
      "text": "Immanuel Kant publishes 'Critique of Pure Reason,' a foundational text in modern Western philosophy that addresses the relationship between human experience and knowledge."
    },
    {
      "date": "1844",
      "headline": "Publication of The Essence of Christianity",
      "text": "Ludwig Feuerbach publishes 'The Essence of Christianity,' which critiques religion and influences later existential and Marxist thought."
    },
    {
      "date": "1889",
      "headline": "Publication of Beyond Good and Evil",
      "text": "Friedrich Nietzsche publishes 'Beyond Good and Evil,' challenging traditional moral values and influencing existential and postmodern philosophy."
    },
    {
      "date": "1921",
      "headline": "Publication of Tractatus Logico-Philosophicus",
      "text": "Ludwig Wittgenstein publishes 'Tractatus Logico-Philosophicus,' a significant work in analytic philosophy that explores the relationship between language and reality."
    },
    {
      "date": "1943",
      "headline": "Publication of Being and Nothingness",
      "text": "Jean-Paul Sartre publishes 'Being and Nothingness,' a key text in existential philosophy that examines the nature of human freedom and consciousness."
    },
    {
      "date": "1971",
      "headline": "Publication of A Theory of Justice",
      "text": "John Rawls publishes 'A Theory of Justice,' introducing the concept of 'justice as fairness' and revitalizing political philosophy."
    }
  ]
}

