      "date": "-0300",
      "headline": "Earliest Attestation",
      "text": "Tamil is attested as a classical language since around 300 BCE, making it one of the longest-surviving classical languages in India."
    },
    {
      "date": "0200",
      "headline": "Sangam Literature",
      "text": "The earliest Tamil literature, known as Sangam literature, is believed to have been composed between 300 BCE and 300 CE. This body of work includes poetry and prose that reflects the culture and society of ancient Tamilakam."
    },
    {
      "date": "0700",
      "headline": "Bhakti Movement",
      "text": "The Bhakti movement, which began around the 7th century, saw the composition of devotional Tamil poetry by saints such as the Alvars and Nayanars, which contributed significantly to Tamil literature and religious life."
    },
    {
      "date": "1000",
      "headline": "Chola Dynasty Influence",
      "text": "During the Chola dynasty (9th to 13th centuries), Tamil culture and language flourished, with significant contributions to literature, art, and architecture."
    },
    {
      "date": "1600",
      "headline": "European Contact",
      "text": "The arrival of European colonial powers in South India in the 16th century led to increased documentation and study of the Tamil language by missionaries and scholars."
    },
    {
      "date": "1900",
      "headline": "Tamil Renaissance",
      "text": "The late 19th and early 20th centuries saw a Tamil renaissance, with increased interest in Tamil literature, culture, and identity, leading to the revival and modernization of the language."
    },
    {
      "date": "1956",
      "headline": "Official Language Status",
      "text": "Tamil was declared the official language of the Indian state of Tamil Nadu in 1956, reinforcing its importance in regional administration and education."
    },
    {
      "date": "2004",
      "headline": "Classical Language Status",
      "text": "In 2004, the Government of India declared Tamil a classical language, recognizing its ancient origins and rich literary tradition."
    }
  ]
}

