{
  "timeline": [
    {
      "date": "-0160",
      "headline": "Early Origins",
      "text": "The roots of the yakuza can be traced back to the 17th century during the Edo period in Japan. The yakuza evolved from two groups: tekiya, who were peddlers, and bakuto, who were gamblers."
    },
    {
      "date": "1603",
      "headline": "Edo Period",
      "text": "During the Edo period (1603-1868), the yakuza began to form as organized groups. Tekiya and bakuto were recognized as separate entities, with tekiya involved in street peddling and bakuto in gambling."
    },
    {
      "date": "1868",
      "headline": "Meiji Restoration",
      "text": "The Meiji Restoration in 1868 led to the modernization of Japan, and the yakuza adapted by becoming more structured and organized, often involving themselves in political and economic activities."
    },
    {
      "date": "1945",
      "headline": "Post-World War II Expansion",
      "text": "After World War II, Japan's economy was in disarray, and the yakuza expanded rapidly, engaging in black market activities and gaining influence in various sectors."
    },
    {
      "date": "1960",
      "headline": "Yakuza Influence Peaks",
      "text": "By the 1960s, the yakuza had reached the height of their power, with an estimated membership of over 200,000. They were involved in various illegal activities, including drug trafficking, extortion, and gambling."
    },
    {
      "date": "1992",
      "headline": "Anti-Boryokudan Law",
      "text": "In 1992, the Japanese government enacted the Anti-Boryokudan Law to curb yakuza activities. This law made it illegal for businesses to associate with yakuza members and aimed to reduce their influence."
    },
    {
      "date": "2011",
      "headline": "Further Crackdowns",
      "text": "In 2011, additional laws were introduced to further restrict yakuza activities, including measures to prevent them from opening bank accounts and leasing property."
    },
    {
      "date": "2020",
      "headline": "Decline in Membership",
      "text": "By 2020, yakuza membership had significantly declined due to increased legal pressure and societal changes, with estimates of around 25,900 members remaining."
    }
  ]
}

