{
  "timeline": [
    {
      "date": "-0184",
      "headline": "Early Socialistic Ideas",
      "text": "The earliest recorded ideas resembling socialism can be traced back to ancient Greece, with the philosopher Plato's work 'The Republic', which described a society where property was communal."
    },
    {
      "date": "1516",
      "headline": "Publication of 'Utopia'",
      "text": "Thomas More published 'Utopia', a book that depicted a fictional island society with communal ownership of property, influencing later socialist thought."
    },
    {
      "date": "1776",
      "headline": "Adam Smith's 'The Wealth of Nations'",
      "text": "While not socialist, Adam Smith's work laid the groundwork for economic thought, against which socialist ideas would later react."
    },
    {
      "date": "1825",
      "headline": "Robert Owen's New Harmony",
      "text": "Robert Owen, a Welsh industrialist and social reformer, attempted to create a utopian socialist community in New Harmony, Indiana, USA."
    },
    {
      "date": "1848",
      "headline": "Publication of 'The Communist Manifesto'",
      "text": "Karl Marx and Friedrich Engels published 'The Communist Manifesto', which became a foundational text for socialist movements worldwide."
    },
    {
      "date": "1864",
      "headline": "First International",
      "text": "The International Workingmen's Association, known as the First International, was founded in London, aiming to unite various socialist, communist, and anarchist groups."
    },
    {
      "date": "1871",
      "headline": "Paris Commune",
      "text": "The Paris Commune was a radical socialist and revolutionary government that ruled Paris from March 18 to May 28, 1871."
    },
    {
      "date": "1889",
      "headline": "Second International",
      "text": "The Second International was founded in Paris, continuing the work of the First International and promoting socialist ideas globally."
    },
    {
      "date": "1917",
      "headline": "Russian Revolution",
      "text": "The Bolshevik Party, led by Vladimir Lenin, overthrew the Russian Provisional Government, leading to the establishment of a socialist state."
    },
    {
      "date": "1949",
      "headline": "Establishment of the People's Republic of China",
      "text": "The Chinese Communist Party, led by Mao Zedong, established the People's Republic of China, implementing socialist policies."
    },
    {
      "date": "1959",
      "headline": "Cuban Revolution",
      "text": "Fidel Castro and his revolutionary forces overthrew the Cuban government, establishing a socialist state in Cuba."
    },
    {
      "date": "1989",
      "headline": "Fall of the Berlin Wall",
      "text": "The fall of the Berlin Wall symbolized the collapse of socialist regimes in Eastern Europe and the end of the Cold War."
    },
    {
      "date": "1991",
      "headline": "Dissolution of the Soviet Union",
      "text": "The Soviet Union dissolved, marking the end of the largest socialist state and a significant shift in global political dynamics."
    },
    {
      "date": "2000s",
      "headline": "Rise of Democratic Socialism",
      "text": "Democratic socialism gained popularity in various countries, advocating for socialist policies within a democratic framework."
