{
  "timeline": [
    {
      "date": "-1500",
      "headline": "Origins of Diwali",
      "text": "The origins of Diwali can be traced back to ancient India, as a festival after the summer harvest in the Hindu calendar month of Kartika. It is mentioned in early Sanskrit texts, indicating its celebration as early as 1500 BCE."
    },
    {
      "date": "-1000",
      "headline": "Association with Ramayana",
      "text": "Diwali is linked to the return of Lord Rama, his wife Sita, and his brother Lakshmana to Ayodhya after a 14-year exile, as described in the epic Ramayana. The people of Ayodhya lit oil lamps to celebrate their return, marking the festival's association with light."
    },
    {
      "date": "0000",
      "headline": "Jain Celebration of Diwali",
      "text": "Diwali is also significant in Jainism as it marks the nirvana, or spiritual awakening, of Lord Mahavira in 527 BCE. Jains celebrate Diwali as a day of liberation and enlightenment."
    },
    {
      "date": "1577",
      "headline": "Sikh Celebration of Diwali",
      "text": "In Sikhism, Diwali is celebrated to mark the release of Guru Hargobind Ji and 52 other princes from the Gwalior Fort in 1619. The event is known as Bandi Chhor Divas, which coincides with Diwali."
    },
    {
      "date": "1900",
      "headline": "Modern Celebrations",
      "text": "By the 20th century, Diwali had become a major festival celebrated by Hindus, Jains, Sikhs, and some Buddhists across India and the world. It involves lighting oil lamps, bursting fireworks, and sharing sweets."
    },
    {
      "date": "2023",
      "headline": "Global Celebration",
      "text": "Today, Diwali is celebrated globally, with major public events in countries with significant Indian populations, such as the United States, United Kingdom, Australia, and Canada. It is recognized as a public holiday in several countries."
    }
  ]
}

