{
  "timeline": [
    {
      "date": "-0431",
      "headline": "Ancient Celtic Festival of Samhain",
      "text": "The origins of Halloween can be traced back to the ancient Celtic festival of Samhain, which was celebrated around October 31. The Celts believed that on this day, the boundary between the living and the dead was blurred, and ghosts of the dead returned to earth."
    },
    {
      "date": "0609-05-13",
      "headline": "Establishment of All Saints' Day",
      "text": "Pope Boniface IV established All Saints' Day, originally celebrated on May 13, to honor all saints and martyrs. This was later moved to November 1, influencing the development of Halloween."
    },
    {
      "date": "1000",
      "headline": "All Souls' Day Added",
      "text": "The church made November 2 All Souls' Day, a day to honor the dead. It was celebrated similarly to Samhain, with bonfires, parades, and dressing up in costumes as saints, angels, and devils."
    },
    {
      "date": "1000-11-01",
      "headline": "All Hallows' Eve",
      "text": "The evening before All Saints' Day became known as All Hallows' Eve, eventually evolving into Halloween. It incorporated elements of the Celtic Samhain festival."
    },
    {
      "date": "1600s",
      "headline": "Halloween Traditions in America",
      "text": "Halloween traditions began to emerge in America, influenced by European immigrants. Celebrations included 'play parties,' public events to celebrate the harvest, where neighbors would share stories of the dead, tell each other's fortunes, dance, and sing."
    },
    {
      "date": "1800s",
      "headline": "Irish and Scottish Influence",
      "text": "The influx of Irish and Scottish immigrants to America in the 19th century popularized Halloween. They brought with them traditions such as 'guising' and 'souling,' which evolved into modern trick-or-treating."
    },
    {
      "date": "1920s",
      "headline": "Community-Based Celebrations",
      "text": "By the 1920s and 1930s, Halloween had become a secular, community-centered holiday, with parades and town-wide parties as the featured entertainment."
    },
    {
      "date": "1950s",
      "headline": "Trick-or-Treating Becomes Popular",
      "text": "Trick-or-treating became a widespread practice in the United States during the 1950s, as the holiday became more child-centered."
    },
    {
      "date": "2000s",
      "headline": "Global Popularity",
      "text": "Halloween has grown into a globally recognized holiday, celebrated in many countries with costume parties, haunted attractions, and themed events."
    }
  ]
}

