      "date": "1817",
      "headline": "First Description of Parkinson's Disease",
      "text": "James Parkinson, an English surgeon, published 'An Essay on the Shaking Palsy,' which is the first detailed description of the condition that would later bear his name."
    },
    {
      "date": "1872",
      "headline": "Parkinson's Disease Named",
      "text": "Jean-Martin Charcot, a French neurologist, named the disease 'Parkinson's disease' in honor of James Parkinson's work."
    },
    {
      "date": "1912",
      "headline": "Lewy Bodies Identified",
      "text": "Frederic Lewy, a German neurologist, discovered abnormal protein deposits in the brains of people with Parkinson's disease, later known as Lewy bodies."
    },
    {
      "date": "1957",
      "headline": "Dopamine's Role Discovered",
      "text": "Arvid Carlsson, a Swedish scientist, discovered the role of dopamine as a neurotransmitter in the brain, which is crucial for understanding Parkinson's disease."
    },
    {
      "date": "1960",
      "headline": "Dopamine Deficiency Identified",
      "text": "Researchers identified that Parkinson's disease is associated with a deficiency of dopamine in the brain."
    },
    {
      "date": "1967",
      "headline": "Levodopa Treatment Introduced",
      "text": "Levodopa, a precursor to dopamine, was introduced as a treatment for Parkinson's disease, significantly improving symptoms in many patients."
    },
    {
      "date": "1983",
      "headline": "MPTP-Induced Parkinsonism",
      "text": "The discovery that the compound MPTP can induce Parkinsonism in humans and primates provided a new model for studying the disease."
    },
    {
      "date": "1997",
      "headline": "Alpha-Synuclein Linked to Parkinson's",
      "text": "Mutations in the alpha-synuclein gene were identified as a cause of familial Parkinson's disease, highlighting the role of this protein in the disease's pathology."
    },
    {
      "date": "2002",
      "headline": "Deep Brain Stimulation Approved",
      "text": "The FDA approved deep brain stimulation as a treatment for Parkinson's disease, offering a surgical option to manage symptoms."
    },
    {
      "date": "2004",
      "headline": "Parkin Gene Mutation Identified",
      "text": "Mutations in the parkin gene were linked to early-onset Parkinson's disease, expanding the understanding of genetic factors in the disease."
    }
  ]
}

