{
  "timeline": [
    {
      "date": "-04500",
      "headline": "Proto-Indo-European Language",
      "text": "The Proto-Indo-European language is believed to have been spoken around 4500 BCE. It is the reconstructed common ancestor of the Indo-European language family."
    },
    {
      "date": "-03000",
      "headline": "Indo-European Migrations",
      "text": "Around 3000 BCE, the Indo-European migrations began, spreading the Proto-Indo-European language and its dialects across Europe and Asia."
    },
    {
      "date": "-02000",
      "headline": "Emergence of Distinct Branches",
      "text": "By 2000 BCE, distinct branches of the Indo-European languages began to emerge, such as the Anatolian and Tocharian branches."
    },
    {
      "date": "-01500",
      "headline": "Indo-Iranian Branch",
      "text": "Around 1500 BCE, the Indo-Iranian branch of the Indo-European languages began to form, leading to the development of languages like Sanskrit and Avestan."
    },
    {
      "date": "-01200",
      "headline": "Hittite Language",
      "text": "The Hittite language, an early Indo-European language, was used in Anatolia around 1200 BCE and is one of the earliest attested Indo-European languages."
    },
    {
      "date": "-0800",
      "headline": "Greek Language",
      "text": "By 800 BCE, the Greek language, part of the Hellenic branch, was well-established and used in the composition of works like Homer's epics."
    },
    {
      "date": "-0500",
      "headline": "Italic Languages",
      "text": "Around 500 BCE, the Italic languages, including Latin, began to develop in the Italian Peninsula."
    },
    {
      "date": "0500",
      "headline": "Germanic Languages",
      "text": "By 500 CE, the Germanic languages had spread across much of Europe, with Old English, Old High German, and Old Norse among them."
    },
    {
      "date": "0800",
      "headline": "Slavic Languages",
      "text": "Around 800 CE, the Slavic languages began to differentiate, leading to the development of languages such as Russian, Polish, and Czech."
    },
    {
      "date": "1000",
      "headline": "Romance Languages",
      "text": "By 1000 CE, the Romance languages, derived from Latin, were well-established in regions of the former Roman Empire, including French, Spanish, and Italian."
    },
    {
      "date": "1500",
      "headline": "Colonial Expansion",
      "text": "During the 1500s, European colonial expansion spread Indo-European languages such as Spanish, Portuguese, English, and French to the Americas, Africa, and Asia."
    },
    {
      "date": "1800",
      "headline": "Indo-European Studies",
      "text": "In the 19th century, the field of Indo-European studies emerged, with scholars reconstructing the Proto-Indo-European language and studying its branches."
    }
  ]
}

