{
  "timeline": [
    {
      "date": "-09500",
      "headline": "Initial Construction",
      "text": "Göbekli Tepe begins construction around 9500 BCE. It is one of the earliest known examples of monumental architecture, featuring large circular structures with massive stone pillars."
    },
    {
      "date": "-09500",
      "headline": "Pre-Pottery Neolithic A Period",
      "text": "The site is primarily active during the Pre-Pottery Neolithic A period, characterized by the lack of pottery and the use of stone tools."
    },
    {
      "date": "-09000",
      "headline": "Development of Megalithic Structures",
      "text": "By around 9000 BCE, Göbekli Tepe's megalithic structures are fully developed, with T-shaped pillars arranged in circles, some of which are decorated with intricate carvings of animals and abstract symbols."
    },
    {
      "date": "-08000",
      "headline": "End of Major Construction",
      "text": "Major construction activities at Göbekli Tepe cease around 8000 BCE. The site continues to be used, but the focus shifts from monumental building to smaller, domestic structures."
    },
    {
      "date": "-08000",
      "headline": "Pre-Pottery Neolithic B Period",
      "text": "During this period, the site sees a transition in its use and possibly its cultural significance, as indicated by changes in the architectural style and the types of artifacts found."
    },
    {
      "date": "-07500",
      "headline": "Site Abandonment",
      "text": "Göbekli Tepe is gradually abandoned around 7500 BCE. The reasons for its abandonment are not fully understood, but it may be related to changes in climate, resources, or social structures."
    },
    {
      "date": "1963",
      "headline": "Rediscovery",
      "text": "Göbekli Tepe is rediscovered in 1963 during a survey conducted by Istanbul University and the University of Chicago, although its significance is not immediately recognized."
    },
    {
      "date": "1994",
      "headline": "Excavations Begin",
      "text": "Klaus Schmidt of the German Archaeological Institute begins systematic excavations at Göbekli Tepe, revealing its importance as a prehistoric site."
    },
    {
      "date": "2018",
      "headline": "UNESCO World Heritage Site",
      "text": "Göbekli Tepe is designated as a UNESCO World Heritage Site, recognizing its global significance as one of the earliest examples of monumental architecture."
    }
  ]
}

