{
  "timeline": [
    {
      "date": "-0300",
      "headline": "Sangam Period",
      "text": "The Sangam period is a historical era in Tamil Nadu, dating from around 300 BCE to 300 CE, known for its significant contributions to Tamil literature and culture."
    },
    {
      "date": "0300",
      "headline": "Post-Sangam Period",
      "text": "Following the Sangam period, Tamil Nadu saw the rise of the Pallavas, Cholas, and Pandyas, who contributed to the region's cultural and architectural development."
    },
    {
      "date": "0600",
      "headline": "Rise of the Pallava Dynasty",
      "text": "The Pallava dynasty emerged as a dominant power in Tamil Nadu, known for their patronage of architecture, including the rock-cut temples at Mahabalipuram."
    },
    {
      "date": "0900",
      "headline": "Chola Dynasty Expansion",
      "text": "The Chola dynasty expanded its influence across South India and Southeast Asia, renowned for its naval power and contributions to art and architecture."
    },
    {
      "date": "1300",
      "headline": "Pandya Dynasty Rule",
      "text": "The Pandya dynasty regained control over Tamil Nadu, known for their trade relations and contributions to Tamil literature."
    },
    {
      "date": "1529",
      "headline": "Vijayanagara Empire Influence",
      "text": "The Vijayanagara Empire extended its influence over Tamil Nadu, leading to a period of economic prosperity and cultural development."
    },
    {
      "date": "1674",
      "headline": "Establishment of the Maratha Empire",
      "text": "The Maratha Empire established control over parts of Tamil Nadu, influencing the region's politics and culture."
    },
    {
      "date": "1801",
      "headline": "British Colonial Rule",
      "text": "Tamil Nadu came under British colonial rule as part of the Madras Presidency, significantly impacting its political and economic landscape."
    },
    {
      "date": "1947-08-15",
      "headline": "Independence of India",
      "text": "India gained independence from British rule, and Tamil Nadu became a part of the newly independent nation."
    },
    {
      "date": "1956-11-01",
      "headline": "Formation of Tamil Nadu",
      "text": "The state of Tamil Nadu was officially formed, reorganized from the Madras State, with Chennai as its capital."
    },
    {
      "date": "1967",
      "headline": "Dravidian Movement",
      "text": "The Dravidian movement gained political power in Tamil Nadu, leading to significant social and political changes in the state."
    }
  ]
}

