{
  "timeline": [
    {
      "date": "1918-11-09",
      "headline": "Proclamation of the Weimar Republic",
      "text": "The Weimar Republic was proclaimed on November 9, 1918, following the abdication of Kaiser Wilhelm II and the end of the German Empire. This marked the beginning of Germany's first constitutional federal republic."
    },
    {
      "date": "1919-01-19",
      "headline": "First Weimar Republic Elections",
      "text": "The first elections for the Weimar National Assembly were held on January 19, 1919. The Social Democratic Party of Germany (SPD) emerged as the largest party."
    },
    {
      "date": "1919-02-06",
      "headline": "Weimar National Assembly Convenes",
      "text": "The Weimar National Assembly convened for the first time in the city of Weimar on February 6, 1919, to draft a new constitution for Germany."
    },
    {
      "date": "1919-08-11",
      "headline": "Weimar Constitution Adopted",
      "text": "The Weimar Constitution was adopted on August 11, 1919, establishing Germany as a democratic parliamentary republic with a semi-presidential system."
    },
    {
      "date": "1923-01",
      "headline": "Occupation of the Ruhr",
      "text": "In January 1923, French and Belgian troops occupied the Ruhr region in response to Germany's failure to pay reparations, leading to a period of hyperinflation and economic crisis in Germany."
    },
    {
      "date": "1923-11-08",
      "headline": "Beer Hall Putsch",
      "text": "On November 8, 1923, Adolf Hitler and the Nazi Party attempted a coup in Munich known as the Beer Hall Putsch. The coup failed, and Hitler was arrested."
    },
    {
      "date": "1924",
      "headline": "Dawes Plan Implemented",
      "text": "The Dawes Plan was implemented in 1924 to restructure Germany's reparations payments and stabilize the German economy, leading to a period of relative economic stability known as the 'Golden Twenties.'"
    },
    {
      "date": "1925-04-26",
      "headline": "Paul von Hindenburg Elected President",
      "text": "Paul von Hindenburg was elected President of the Weimar Republic on April 26, 1925, succeeding Friedrich Ebert."
    },
    {
      "date": "1929-10",
      "headline": "Great Depression Begins",
      "text": "The global economic downturn known as the Great Depression began in October 1929, severely impacting the German economy and leading to increased political instability."
    },
    {
      "date": "1930-03-30",
      "headline": "Heinrich Brüning Appointed Chancellor",
      "text": "Heinrich Brüning was appointed Chancellor of Germany on March 30, 1930. His government relied heavily on emergency decrees to pass legislation."
    },
    {
      "date": "1932-07-31",
      "headline": "Nazi Party Wins Largest Share in Reichstag Elections",
      "text": "In the Reichstag elections held on July 31, 1932, the Nazi Party became the largest party in the Reichstag, although they did not achieve an outright majority."
    },
    {
      "date": "1933-01-30",
      "headline": "Adolf Hitler Appointed Chancellor",
      "text": "Adolf Hitler was appointed Chancellor of Germany on January 30, 1933, marking the beginning of the end for the Weimar Republic."
    },
    {
      "date": "1933-02-27",
      "headline": "Reichstag Fire",
      "text": "The Reichstag building was set on fire on February 27, 1933. The Nazis used the event to justify the suspension of civil liberties and the arrest of political opponents."
    },
    {
      "date": "1933-03-23",
      "headline": "Enabling Act Passed",
      "text": "The Enabling Act was passed on March 23, 1933, granting Hitler's government the power to enact laws without the Reichstag's consent, effectively ending the Weimar Republic and establishing a dictatorship."
    }
  ]
}

