      "date": "1526",
      "headline": "Mughal Empire Establishment",
      "text": "The Mughal Empire was established in Delhi after Babur defeated Ibrahim Lodi at the First Battle of Panipat in 1526."
    },
    {
      "date": "1639",
      "headline": "Foundation of Shahjahanabad",
      "text": "Emperor Shah Jahan founded the city of Shahjahanabad in 1639, which is now known as Old Delhi."
    },
    {
      "date": "1803",
      "headline": "British Control",
      "text": "Delhi came under British control in 1803 after the Second Anglo-Maratha War."
    },
    {
      "date": "1911",
      "headline": "Delhi Becomes Capital of British India",
      "text": "The capital of British India was shifted from Calcutta to Delhi in 1911."
    },
    {
      "date": "1947",
      "headline": "Independence and Partition",
      "text": "India gained independence from British rule in 1947, and Delhi became the capital of the newly independent India."
    },
    {
      "date": "1956-11-01",
      "headline": "Delhi Becomes a Union Territory",
      "text": "Delhi was officially declared a Union Territory of India on November 1, 1956."
