{
  "timeline": [
    {
      "date": "-2000",
      "headline": "Origin of Eukaryotes",
      "text": "Eukaryotes are believed to have originated around 2 billion years ago. This marks the emergence of cells with a membrane-bound nucleus, distinguishing them from prokaryotes."
    },
    {
      "date": "-1600",
      "headline": "Endosymbiotic Theory",
      "text": "Around 1.6 billion years ago, the endosymbiotic theory suggests that eukaryotic cells acquired mitochondria through a symbiotic relationship with a proteobacterium."
    },
    {
      "date": "-1500",
      "headline": "Acquisition of Chloroplasts",
      "text": "Approximately 1.5 billion years ago, some eukaryotic cells acquired chloroplasts through a symbiotic relationship with cyanobacteria, leading to the evolution of photosynthetic eukaryotes."
    },
    {
      "date": "-1000",
      "headline": "Diversification of Eukaryotes",
      "text": "By around 1 billion years ago, eukaryotes had diversified into various lineages, including the ancestors of modern plants, animals, and fungi."
    },
    {
      "date": "-600",
      "headline": "Ediacaran Biota",
      "text": "Around 600 million years ago, the Ediacaran biota, consisting of early multicellular eukaryotic organisms, appeared in the fossil record."
    },
    {
      "date": "-541",
      "headline": "Cambrian Explosion",
      "text": "The Cambrian Explosion, beginning around 541 million years ago, saw a rapid diversification of eukaryotic life forms, including the ancestors of most modern animal phyla."
    },
    {
      "date": "-470",
      "headline": "Colonization of Land",
      "text": "Around 470 million years ago, eukaryotic plants began to colonize land, leading to the development of terrestrial ecosystems."
    },
    {
      "date": "-400",
      "headline": "Evolution of Fungi",
      "text": "Fungi are believed to have evolved around 400 million years ago, playing a crucial role in the decomposition of organic matter and nutrient cycling."
    },
    {
      "date": "-200",
      "headline": "Rise of Dinosaurs",
      "text": "Approximately 200 million years ago, during the Mesozoic Era, eukaryotic dinosaurs became the dominant terrestrial vertebrates."
    },
    {
      "date": "-66",
      "headline": "Cretaceous-Paleogene Extinction Event",
      "text": "Around 66 million years ago, a mass extinction event led to the demise of the dinosaurs, paving the way for the rise of mammals and birds, both eukaryotic groups."
    },
    {
      "date": "-2.5",
      "headline": "Emergence of Homo Genus",
      "text": "Around 2.5 million years ago, the Homo genus, including modern humans, emerged as part of the eukaryotic lineage."
    }
  ]
}

