{
  "timeline": [
    {
      "date": "-0155",
      "headline": "Earliest Known Description",
      "text": "The earliest known written description of leprosy is found in the Ebers Papyrus from Egypt, dating back to around 1550 BCE."
    },
    {
      "date": "0180",
      "headline": "Galen's Description",
      "text": "The Greek physician Galen provided one of the earliest detailed descriptions of leprosy in his medical writings."
    },
    {
      "date": "0628",
      "headline": "Leprosy in the Quran",
      "text": "Leprosy is mentioned in the Quran, indicating its presence and recognition in the Arabian Peninsula during the 7th century."
    },
    {
      "date": "1100",
      "headline": "Leprosy Epidemic in Europe",
      "text": "Leprosy became widespread in Europe during the Middle Ages, leading to the establishment of numerous leper colonies."
    },
    {
      "date": "1873",
      "headline": "Discovery of Mycobacterium leprae",
      "text": "Norwegian physician Gerhard Armauer Hansen discovered Mycobacterium leprae, the bacterium that causes leprosy, marking the first identification of a bacterium as the cause of a human disease."
    },
    {
      "date": "1940",
      "headline": "Introduction of Dapsone",
      "text": "Dapsone was introduced as the first effective treatment for leprosy, significantly improving patient outcomes."
    },
    {
      "date": "1981",
      "headline": "WHO Recommends Multi-Drug Therapy",
      "text": "The World Health Organization recommended a multi-drug therapy (MDT) regimen for leprosy, which became the standard treatment and led to a dramatic decrease in the global prevalence of the disease."
    },
    {
      "date": "1995",
      "headline": "Free MDT Distribution by WHO",
      "text": "The World Health Organization began providing free multi-drug therapy to all leprosy patients worldwide, further reducing the disease's impact."
    },
    {
      "date": "2000",
      "headline": "Leprosy Elimination as a Public Health Problem",
      "text": "Leprosy was officially eliminated as a public health problem globally, defined as a prevalence rate of less than 1 case per 10,000 people."
    }
  ]
}

