{
  "timeline": [
    {
      "date": "1893",
      "headline": "Discovery of Methamphetamine",
      "text": "Methamphetamine was first synthesized by the Japanese chemist Nagai Nagayoshi. He isolated the compound from ephedrine, marking the discovery of methamphetamine."
    },
    {
      "date": "1919",
      "headline": "Synthesis of Methamphetamine Hydrochloride",
      "text": "Akira Ogata, a Japanese chemist, synthesized methamphetamine hydrochloride, a crystalline form of the drug, by reducing ephedrine using red phosphorus and iodine."
    },
    {
      "date": "1930s",
      "headline": "Introduction as a Medical Treatment",
      "text": "Methamphetamine began to be used medically in the 1930s, primarily for its stimulant effects. It was marketed under the name Methedrine."
    },
    {
      "date": "1940s",
      "headline": "Use During World War II",
      "text": "Methamphetamine was widely used by military forces during World War II to keep troops awake and alert. It was distributed under the brand name Pervitin in Germany."
    },
    {
      "date": "1950s",
      "headline": "Rise in Recreational Use",
      "text": "The 1950s saw an increase in the recreational use of methamphetamine, leading to concerns about its addictive properties and potential for abuse."
    },
    {
      "date": "1970",
      "headline": "Controlled Substances Act",
      "text": "The United States classified methamphetamine as a Schedule II controlled substance under the Controlled Substances Act, recognizing its high potential for abuse and limited medical use."
    },
    {
      "date": "1980s",
      "headline": "Crystal Meth Epidemic",
      "text": "The 1980s witnessed a surge in the production and use of crystal meth, a potent form of methamphetamine, leading to widespread addiction and social issues."
    },
    {
      "date": "2000s",
      "headline": "Combat Methamphetamine Epidemic Act",
      "text": "In response to the growing methamphetamine crisis, the U.S. government passed the Combat Methamphetamine Epidemic Act in 2005, regulating the sale of precursor chemicals used in its production."
    },
    {
      "date": "2010s",
      "headline": "Research into Medical Uses",
      "text": "Research continued into potential medical uses of methamphetamine, including its use as a treatment for ADHD and traumatic brain injury, though concerns about its safety remained."
    }
  ]
}

