    },
    {
      "date": "2001",
      "headline": "El Chapo's Escape from Prison",
      "text": "Joaquín 'El Chapo' Guzmán escaped from Puente Grande, a maximum-security prison in Jalisco, Mexico, reportedly by hiding in a laundry cart."
    },
    {
      "date": "2008",
      "headline": "Sinaloa Cartel's Expansion",
      "text": "The Sinaloa Cartel expanded its operations significantly, becoming one of the most powerful drug trafficking organizations in the world, with operations in over 50 countries."
    },
    {
      "date": "2014-02-22",
      "headline": "El Chapo's Recapture",
      "text": "Joaquín 'El Chapo' Guzmán was recaptured by Mexican authorities in Mazatlán, Sinaloa, after 13 years on the run."
    },
    {
      "date": "2015-07-11",
      "headline": "El Chapo's Second Escape",
      "text": "El Chapo escaped from the Altiplano maximum-security prison in Almoloya de Juárez, Mexico, through a tunnel leading from his cell."
    },
    {
      "date": "2016-01-08",
      "headline": "El Chapo's Final Recapture",
      "text": "Joaquín 'El Chapo' Guzmán was recaptured by Mexican authorities in Los Mochis, Sinaloa, after a shootout."
    },
    {
      "date": "2017-01-19",
      "headline": "Extradition to the United States",
      "text": "El Chapo was extradited to the United States to face charges of drug trafficking, money laundering, and other crimes."
    },
    {
      "date": "2019-02-12",
      "headline": "El Chapo's Conviction",
      "text": "Joaquín 'El Chapo' Guzmán was found guilty on all counts in a U.S. federal court, including drug trafficking, money laundering, and engaging in a criminal enterprise."
    },
    {
      "date": "2019-07-17",
      "headline": "El Chapo's Sentencing",
      "text": "El Chapo was sentenced to life in prison plus 30 years by a U.S. federal judge and ordered to forfeit $12.6 billion."
